              var RB = LG.rvBook, NM2 = { floor: "the floor", strip: "the stage", pole: "the pole", lap: "the booths", glory: "the back hall", bound: "the stocks", group: "the late show", private: "upstairs", oil: "the oil show", window: "the window", wheel: "the wheel", leash: "the leash", raffle: "the raffle" };
              body.appendChild(h("div", { class: "note", style: "color:#e7e5e4" }, RB.nights + " nights at " + RB.name + ", " + RB.earned + " gold earned" + (RB.owe ? ", " + RB.owe + " still owed to him." : ".")));
