            ".shelfrow{cursor:grab;user-select:none}.shelfrow.dragging{cursor:grabbing}.shelfrow.dragging .cslot{pointer-events:none}",
            ".shelfrow{position:relative}.shelfrow .cslot{touch-action:none;user-select:none;-webkit-user-select:none}.shelfrow .cslot img{-webkit-user-drag:none;user-drag:none;pointer-events:none}.shelfrow.reorder,.shelfrow.reorder .cslot{cursor:grabbing}.cslot.lifted{opacity:.3;filter:grayscale(.6)}.shelfmark{position:absolute;width:4px;border-radius:2px;background:#d6a85c;box-shadow:0 0 8px rgba(214,168,92,.7);pointer-events:none;z-index:5}.shelfghost .clabel{display:none}",
            /* two rows of cases, with a plank under the top one (it scrolls with them) */
            ".shelfrow.two{display:grid;grid-auto-flow:column;grid-template-rows:repeat(2,186px);grid-auto-columns:max-content;column-gap:14px;row-gap:22px;align-items:end;background:linear-gradient(180deg,#8a5a34 0%,#6b4226 45%,#3d2414 100%) 0 204px/100% 12px no-repeat;background-attachment:local}",
