            ".cslot{flex:0 0 auto;background:none;border:0;padding:0;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px;transition:transform .25s}",
            ".cslot .case{transform:rotateY(16deg) scale(.9);transform-origin:50% 100%;transition:transform .25s,box-shadow .25s,filter .25s;filter:brightness(.78) saturate(.85)}",
