            ".whyc{border:1px solid #44403c;border-radius:8px;padding:8px 10px;margin:6px 0;background:#1f1b19}.whyc.ok{border-color:#3f6212}.whyh{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.whyn{font-weight:600;color:#f5f5f4;font-size:13px}.whys{font-size:11px;color:#fdba74;border:1px solid #7c2d12;border-radius:10px;padding:1px 8px}.whyc.ok .whys{color:#bef264;border-color:#3f6212}.whyl{margin:6px 0 0;padding-left:18px;color:#d6d3d1;font-size:12.5px;line-height:1.55}",
