var KN={nightsAdd:'\u{1F319} Theme nights',mind:'\u{1F319} Her mind',quests:'\u{1F4DC} Quest',scenes:'\u{1F5BC} Scene',encounters:'\u{1F4AC} Her ask',requests:'\u{1F64B} Your request',routines:'\u{1F4C5} Routine',actions:'\u{1F446} Action',tables:'\u{1F3B2} Random encounter',novels:'\u{1F4D6} Visual novel',shows:'\u{1F3AD} Show',quests:'\u{1F4DC} Quest',maps:'\u{1F5FA} Map',dungeons:'\u{1F573} Dungeon',characters:'\u{1F464} Character',scenarios:'Scenario',adventures:'Adventure',party:'Battle rules',pkinds:'Kind of patron',bonds:'Bond',socials:'Their own action',shops:'\u{1F6D2} Shop',items:'\u{1F392} Item',outfits:'\u{1F457} Clothes',flags:'\u{1F6A9} Flag',statuses:'\u2728 Status',elements:'\u{1F525} Element'};
var STORYK={encounters:1,requests:1,routines:1,actions:1,tables:1,novels:1,shows:1,quests:1};
/** Every place in the project that names them: [{kind, i, item, at (a map's place or a dungeon's square), what}] */
function whereIs(P,id){var out=[],seen={};
  Object.keys(P).forEach(function(kind){var L=P[kind];if((kind==='party'||kind==='nightsAdd'||kind==='mind')&&L&&typeof L==='object'&&!Array.isArray(L))L=[L];if(!Array.isArray(L))return;L.forEach(function(item,i){if(!item||typeof item!=='object'||item.id===id||(kind==='flags'&&item.key===id))return;
    (function walk(o,path){if(o==null)return;if(typeof o==='string'){if(o===id&&!(kind==='party'&&/^(id|key)$/.test(path[path.length-1])&&/^(zones|traits|titles|team|positions|tavfights)$/.test(path[path.length-3]))){var at='',what=path[0]||'';if(kind==='maps'&&path[0]==='tiles'){var t=item.tiles[path[1]];at=t.x+','+t.y;what='at '+t.name}else if(kind==='dungeons'&&path[0]==='cells'){var c=item.cells[path[1]];at=c.x+','+c.y;what='square '+at+(c.name?' ('+c.name+')':'')}
      else if(path.indexOf('cast')>=0)what='in its cast';else if(path.indexOf('enemies')>=0||path.indexOf('group')>=0)what='in a fight';else if(path.indexOf('join')>=0)what='joins you';else if(path.indexOf('leave')>=0)what='leaves you';else if(path.indexOf('lover')>=0)what='as her lover';else if(path.indexOf('kinds')>=0)what='in a fight in the tavern';else if(path.indexOf('conds')>=0)what='checked';else if(path.indexOf('flags')>=0)what='changed';else if(path.indexOf('inflict')>=0)what='inflicted';else if(path.indexOf('cure')>=0)what='cured';else if(path[path.length-1]==='zone')what='works on it';else if(path[path.length-1]==='record')what='counts it';else if(path.indexOf('element')>=0||path.indexOf('elements')>=0)what='its element';else what='';
      var k=kind+':'+i+':'+at+':'+what;if(!seen[k]){seen[k]=1;out.push({kind:kind,i:i,item:item,at:at,what:what})}}return}
      if(typeof o!=='object')return;if(Array.isArray(o))o.forEach(function(v,j){walk(v,path.concat([j]))});else Object.keys(o).forEach(function(k2){walk(o[k2],path.concat([k2]))})})(item,[]);
  })});return out}
/** Nothing in the project names it (a character who is never met, an item never sold, found, given or used, clothes
 *  never sold): a \u26A0 in the list. In the tavern, or for sale in the game's own shops, counts as somewhere. */
// 3) a name in what is said: whole words, in text the player reads (not ids, keys, tags or other names)
var SAYK={text:1,reply:1,ask:1,desc:1,description:1,label:1,keepText:1,leaveText:1,lockedText:1,stopText:1,unsure:1,line:1,greet:1,refuse:1};
function nameRe(old){var sp='.*+?^$(){}|[]'+String.fromCharCode(92),e=old.split('').map(function(c){return sp.indexOf(c)>=0?String.fromCharCode(92)+c:c}).join('');return new RegExp('(^|[^A-Za-z0-9_])('+e+')(?![A-Za-z0-9_])','g')}
function walkSaid(P,fn){(function w(o,k,par){if(o==null)return;if(typeof o==='string'){if(SAYK[k]&&par)fn(par,k);return}if(typeof o!=='object')return;if(Array.isArray(o)){o.forEach(function(v,i){if(typeof v==='string'&&k==='keep')fn(o,i);else w(v,k,o)});return}Object.keys(o).forEach(function(kk){w(o[kk],kk,o)})})(P,'',null)}
function renameCount(P,old,id){var re=nameRe(old),n=0;walkSaid(P,function(o,k){var m=String(o[k]).match(re);if(m)n+=m.length});return n}
function renameAll(P,old,now,id){var re=nameRe(old);walkSaid(P,function(o,k){o[k]=String(o[k]).replace(re,function(a,pre){return pre+now})})}
// renaming everywhere, with a preview: every place in the project that says the old name, each with what it
// becomes, ticked to change (untick the ones that mean something else)
var SAYK2={hesitantLine:1,refuseLine:1,willLine:1,willLineNo:1,endText:1,hotText:1,line0:1};
function renHits(P,old){var out=[];if(!old)return out;var re=nameRe(old),seen={};
  Object.keys(FORMS).forEach(function(fk){var FF=FORMS[fk];if(FF.single||FF.page||seen[FF.list])return;seen[FF.list]=1;var base=FF.list.split('.');(get(P,FF.list)||[]).forEach(function(x,i){if(!x||typeof x!=='object')return;
    (function w(o,k,path){if(o==null)return;if(typeof o==='string'){if((SAYK[k]||SAYK2[k])&&o.match(re)){re.lastIndex=0;var m=re.exec(o);re.lastIndex=0;var at=m?m.index+m[1].length:0;out.push({fk:fk,i:i,ename:x.name||idOf(x),icon:FF.icon,part:SUBNAME[fk]||FF.one,path:path,str:o,at:at,n:(o.match(re)||[]).length})}return}
      if(typeof o!=='object')return;if(Array.isArray(o)){o.forEach(function(v,j){w(v,typeof v==='string'&&(k==='keep'||k==='lines')?'line':k,path.concat([j]))});return}Object.keys(o).forEach(function(kk){if(kk!=='storyPos')w(o[kk],kk,path.concat([kk]))})})(x,'',base.concat([i]))})});
  return out}
function renSnip(h,old,now){var a=Math.max(0,h.at-40),b=Math.min(h.str.length,h.at+old.length+40);return (a?'\u2026':'')+esc(h.str.slice(a,h.at))+'<del>'+esc(old)+'</del><ins>'+esc(now||old)+'</ins>'+esc(h.str.slice(h.at+old.length,b))+(b<h.str.length?'\u2026':'')}
function renHtml(x){var S=S0(),R=S.ren;if(!R||R.id!==idOf(x))return '';var H=renHits(S.P,R.old),on=H.filter(function(h,k){return !R.off[k]}).length;
  return '<section class="rnpanel" aria-label="Rename everywhere"><div class="h3" style="margin:0 0 8px">Rename \u201C'+esc(R.old)+'\u201D everywhere</div><label class="fl" style="max-width:340px">The new name<input id="rnnew" value="'+esc(R.now||'')+'" placeholder="'+esc(R.old)+'"></label>'+
    (H.length?'<p class="meta" style="margin:10px 0 6px">'+H.length+' place'+(H.length===1?' says':'s say')+' \u201C'+esc(R.old)+'\u201D. Untick any that mean something else.</p><div class="rnlist">'+H.map(function(h,k){return '<label class="rnrow"><input type="checkbox" data-rn="'+k+'"'+(R.off[k]?'':' checked')+'><span><b>'+h.icon+' '+esc(h.part)+' \u201C'+esc(h.ename)+'\u201D'+(h.n>1?' ('+h.n+' times)':'')+'</b><span class="rnsnip">'+renSnip(h,R.old,R.now)+'</span></span></label>'}).join('')+'</div>':'<p class="meta" style="margin:10px 0 6px">Nothing else in this project says \u201C'+esc(R.old)+'\u201D: only its name changes.</p>')+
    '<div class="row" style="gap:8px;margin-top:10px"><button class="btn sm pri" id="rngo"'+(R.now&&R.now.trim()&&R.now.trim()!==R.old?'':' disabled')+'>'+(R.named?'Change the '+on+' ticked':'Rename it'+(on?' and change the '+on+' ticked':''))+'</button><button class="btn sm" id="rnno">'+(R.named?'Leave them as they are':'Cancel')+'</button></div></section>'}
function renApply(){var S=S0(),R=S.ren,now=(R.now||'').trim();if(!now||now===R.old)return;var H=renHits(S.P,R.old),re=nameRe(R.old),n=0;
  change(function(P){var c=CO(P);if(c&&!R.named)c.name=now;H.forEach(function(h,k){if(R.off[k])return;var par=P,p=h.path;for(var j=0;j<p.length-1;j++){par=par&&par[p[j]]}if(!par||typeof par[p[p.length-1]]!=='string')return;par[p[p.length-1]]=par[p[p.length-1]].replace(re,function(a,pre){n++;return pre+now})});S.ren=null});
  ST.ctx.toast('\u201C'+R.old+'\u201D is \u201C'+now+'\u201D now'+(n?', and in '+n+' place'+(n===1?'':'s')+' it was said':'')+'. Undo (Ctrl+Z) takes it back; Save keeps it.')}
// pinned entries, in the search box at the top of the workspace (any project; kept in this browser)
function pinsGet(){try{var a=JSON.parse(localStorage.getItem('wbws:pins')||'[]');return Array.isArray(a)?a:[]}catch(e){return []}}
function pinsPut(a){try{localStorage.setItem('wbws:pins',JSON.stringify(a.slice(0,16)))}catch(e){}}
function pinned(file,id){return pinsGet().some(function(p){return p.file===file&&p.id===id})}
function pinToggle(x){var S=S0(),FF=F(),fk=Object.keys(FORMS).filter(function(k){return FORMS[k]===FF})[0],id=idOf(x),a=pinsGet(),was=pinned(S.file,id);
  if(was)a=a.filter(function(p){return !(p.file===S.file&&p.id===id)});else{var pn=((ST.ctx.projects().filter(function(p){return p.file===S.file})[0])||{}).name||S.file;a.unshift({file:S.file,fname:pn,fk:fk,id:id,name:x.name||id,icon:x.icon||FF.icon,part:SUBNAME[fk]||FF.one})}
  pinsPut(a);ST.ctx.toast(was?'Unpinned.':'Pinned: it is in the search box at the top (click it, with nothing typed).')}
function indexOfId(P,fk,id){var FF=FORMS[fk];if(!FF)return -1;return (get(P,FF.list)||[]).map(idOf).indexOf(id)}
function toolsHtml(x){if(F().single)return '';var S=S0(),pn=pinned(S.file,idOf(x));return '<div class="fotools"><button class="lnk" id="forename">\u270E Rename everywhere\u2026</button><button class="lnk'+(pn?' on':'')+'" id="fopin" aria-pressed="'+(pn?'true':'false')+'">'+(pn?'\u2605 Pinned':'\u2606 Pin it')+'</button></div>'}
function NM(x){if(x&&x.room&&!x.name&&!x.id)return groomName(x.room);return x?(x.name!=null?x.name:x.label!=null?x.label:''):''} // (an action's name is its label)
function lonely(P,x){if(!idOf(x))return false;if(x.wear==='date'||/^ws_do_towel/.test(idOf(x)))return false;/* 4.16.0: clothes for going out are worn on days out (4.17.0: and the towels at the pools) */
  if(/^wsrm_/.test(x.id||''))return false;if(/^wsv_/.test(x.id||'')||(x.keeper!=null&&x.offer!=null))return false;if(/^(wsp|wsm|wst|wsso|snd)_/.test(x.id||'')||(x.shape!=null&&x.tags!=null&&x.kind!=null))return false;if((x.lv!=null&&x.dir!=null)||Array.isArray(x.changes))return false;if(/^ws(a|r|ro|ac)_/.test(x.id||''))return false;if(/^wsq_/.test(x.id||'')&&x.auto)return false;if(/^wss_/.test(x.id||'')&&!whereIs(P,x.id).length)return true;if(x.rules!=null&&x.from!=null)return false;if(x.record!=null||(x.clip!=null&&x.act))return false;if(x.sens!=null&&x.key)return !zoneUses(P,x.key).length;if(Array.isArray(x.who))return false;if(/^wsk_/.test(x.id)&&x.learn!=='taught')return false;if(x.key&&!x.id){if(x.show&&!isFlag(x))return false;return !whereIs(P,x.key).length}if(x.tavern&&x.tavern.on)return false;if(x.buy&&x.buy.on)return false;if(x.found&&x.found.on)return false;if(x.button&&x.button.on)return false;if(/^ws_/.test(x.id)&&x.shop!==false)return false;
  if(/^wsn_/.test(x.id)&&x.role==='ally')return false;return !whereIs(P,x.id).length}
/** How many in each tab appear nowhere (the Projects page shows it). */
