function onF(f){try{return !!(ST.kind&&TABS[ST.kind])&&F()===f}catch(e){return false}}
var LN={cat:null,wait:false,find:'',tries:{}},LNBC=null;
function lnBC(){if(!LNBC&&typeof BroadcastChannel!=='undefined'){LNBC=new BroadcastChannel('wayward-workspace');LNBC.onmessage=function(ev){var r=ev.data||{};if(r.type==='linesres'){LN.wait=false;LN.cat=r.cat||null;LN.err=r.cat?'':'Start or continue a game in the game\u2019s tab: the list of lines comes from the running game.';if(onF(FORMS.lines))draw()}if(r.type==='lntryres'&&r.key){LN.tries[r.key]=r.out||[];var el=document.querySelector('[data-lntryout="'+r.key+'"]');if(el)el.innerHTML=(r.out||[]).map(function(x){return '<div class="lntry">'+esc(x)+'</div>'}).join('')}}}return LNBC}
