function lvParts(P){var o={};LVK.forEach(function(k){o[k[0]]=(get(P,FORMS[k[0]].list)||[]).map(function(x){return x.id}).filter(Boolean)});return o}
function lvSend(m){var f=m.file;LV[f]={wait:true,at:Date.now(),res:(LV[f]||{}).res};lvPaint();try{if(!LVBC&&typeof BroadcastChannel!=='undefined'){LVBC=new BroadcastChannel('wayward-workspace');LVBC.onmessage=function(ev){var r=ev.data||{};if(r.type!=='checkallres'||!r.file)return;LV[r.file]={res:r.res,at:Date.now()};lvPaint()}}if(!LVBC){LV[f]={res:{err:'This browser can\u2019t reach the game\u2019s tab.'},at:Date.now()};return lvPaint()}LVBC.postMessage(m)}catch(e){LV[f]={res:{err:String(e.message||e)},at:Date.now()}}
  setTimeout(function(){if(LV[f]&&LV[f].wait){LV[f]={res:{err:'The game isn\u2019t open in this browser. Open it (and start or continue a game), then check again.'},at:Date.now()};lvPaint()}},3000)}
