    if(!many&&n.kind==='novels')it.push(['Open its blocks',function(){S.level='novel';S.novel=n.id;S.sel='';S.path='';S.px=0;S.py=0;draw()}]);
    if(!many&&(TRYK[n.kind]||n.kind==='block'))it.push(['\u25B6 Try it'+(n.kind==='block'?' from here':''),function(){var b=q('tryit');if(b)b.click()}]);
