    it.push('-',['Copy',function(){copySel()}],['Duplicate',function(){if(copySel(true))pasteClip()}],[many?'Frame around them':'Frame around it',function(){if(many){var b=q('mframe');if(b)b.click()}else addFrame()}],{tints:function(t){change(function(P){P.storyColors=P.storyColors||{};picked().forEach(function(kk){if(t)P.storyColors[kk]=t;else delete P.storyColors[kk]})})}},'-');
    if(n.kind!=='end'&&(n.kind!=='block'||n.id))it.push([many?'Delete them':'Delete',function(){if(many)delPicked();else{var b=q('delbox');if(b)b.click()}}]);
