    h+='<div class="ln" data-line="'+j+'"><div class="row"><span class="lt">'+(LT[l.t]||l.t)+'</span><span style="flex:1"></span><button class="x" data-up="'+j+'" aria-label="Up">\u2191</button><button class="x" data-down="'+j+'" aria-label="Down">\u2193</button><button class="x" data-delline="'+j+'" aria-label="Remove">\xD7</button></div>';
