  if(a==='cmp'){J('/api/review/entry?key='+encodeURIComponent(g.key)+'&file='+encodeURIComponent(p.file)).then(function(e){d.querySelector('.detail').innerHTML=cmpHtml(e.cmp)});return}
  var others=g.pictures.filter(function(x){return x!==p&&!x.keep}).length;
  if(a==='clear'&&!confirm('Keep this drawing and delete the '+others+' other'+(others===1?'':'s')+' of this picture? Ones you kept before stay.'))return;
  fetch('/bridge/api/review/keep-one',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:g.key,file:p.file,clear:a==='clear'})})
